    function wireEpListWheelScroll() {
        var el = document.getElementById('sdEpScroll');
        if (!el || el.dataset.sdWheel === '1') return;
        el.dataset.sdWheel = '1';
        el.addEventListener('wheel', function (e) {
            if (el.scrollHeight <= el.clientHeight + 1) return;
            var st = el.scrollTop;
            var max = Math.max(0, el.scrollHeight - el.clientHeight);
            var dy = e.deltaY;
            if (e.deltaMode === 1) dy *= 16;
            else if (e.deltaMode === 2) dy = dy > 0 ? el.clientHeight : -el.clientHeight;
            var atTop = st <= 0;
            var atBottom = st >= max - 1;
            if ((dy < 0 && atTop) || (dy > 0 && atBottom)) return;
            el.scrollTop = Math.min(max, Math.max(0, st + dy));
            e.preventDefault();
        }, { passive: false });
    }
