    function copyShareUrlFallback(shareUrl, anchorEl) {
        try {
            var ta = document.createElement('textarea');
            ta.value = shareUrl;
            ta.setAttribute('readonly', '');
            ta.style.position = 'fixed';
            ta.style.left = '-9999px';
            document.body.appendChild(ta);
            ta.select();
            var ok = document.execCommand('copy');
            document.body.removeChild(ta);
            if (ok) showSdCopyTooltip(anchorEl);
        } catch (err) { /* ignore */ }
    }

    var sdShareCopyEl = document.getElementById('sdShareCopy');
    if (sdShareCopyEl) {
        sdShareCopyEl.addEventListener('click', function (e) {
            e.stopPropagation();
            var shareUrl = PAGE_URL;
            var self = this;
            if (navigator.clipboard && window.isSecureContext) {
                navigator.clipboard.writeText(shareUrl).then(function () {
                    showSdCopyTooltip(self);
                }).catch(function () {
                    copyShareUrlFallback(shareUrl, self);
                });
                return;
            }
            copyShareUrlFallback(shareUrl, self);
        });
    }
    var sdDescMoreBtn = document.getElementById('sdDescMoreBtn');
